class BodyNode {
    constructor(_x, _y, _length, _angle, _fromThickness, _toThickness, _parent = null) {
        this.x = _x;
        this.y = _y;
        this.length = _length;
        this.angle = _angle;
        this.fromThickness = _fromThickness;
        this.toThickness = _toThickness;
        this.parent = _parent;

        if (this.parent != null) {
            let startPos = this.parent.getEndPos();
            this.x = startPos.x + _x;
            this.y = startPos.y + _y;

            this.angle += this.parent.angle;
        }
    }

    getEndPos() {
        let endX = this.x + this.length * sin(radians(this.angle));
        let endY = this.y + this.length * -cos(radians(this.angle));

        return { x: endX, y: endY };
    }

    drawNode() {
        let fromColor = nowFillColorA;
        let toColor = nowFillColorB;

        drawSketchLine(this.x, this.y, this.angle, this.length, this.fromThickness, this.toThickness, fromColor, toColor);
    }
}




class NYColor {
    constructor(_h, _s, _b, _a = 1.0) {
        this.h = _h;
        this.s = _s;
        this.b = _b;
        this.a = _a;
    }

    copy() {
        return new NYColor(this.h, this.s, this.b, this.a);
    }

    slightRandomize(_hDiff = 10, _sDiff = 12, _bDiff = 12, _aDiff = 0.0) {
        this.h += random(-0.5 * _hDiff, 0.5 * _hDiff);
        this.s += random(-0.5 * _sDiff, 0.5 * _sDiff);
        this.b += random(-0.5 * _bDiff, 0.5 * _bDiff);
        this.a += random(-0.5 * _aDiff, 0.5 * _aDiff);

        this.h = processHue(this.h);
    }

    color() {
        return color(this.h, this.s, this.b, this.a);
    }

    static newRandomColor(_mainHue) {
        let h = processHue(_mainHue + random(-80, 80));
        let s = random(40, 100);
        let b = random(60, 100);

        return new NYColor(h, s, b);
    }
}




// === Tab: draw.js ===
let sketchDensity = 0.3;
let dotDensity = 0.8;

function drawSketchLine(_x, _y, _drawDir, _length, _fromWidth, _toWidth, _fromColor, _toColor) {
    let strokeCount = _length * sketchDensity;

    for (let i = 0; i < strokeCount; i++) {
        var t = i / (strokeCount - 1);

        var nowX = _x + _length * t * sin(radians(_drawDir));
        var nowY = _y + _length * t * -cos(radians(_drawDir));
        let nowThickness = lerp(_fromWidth, _toWidth, t);
        var nowColor = NYLerpColor(_fromColor, _toColor, t);
        nowColor.slightRandomize(60, 40, 40);
        nowColor.a = 0.6;


        noStroke();


        push();
        translate(nowX, nowY);
        rotate(radians(_drawDir + random(-pieceRotRandomness, pieceRotRandomness)));

        strokeWeight(1);
        stroke(0, 0, 6, 0.8);
        fill(nowColor.h, nowColor.s, nowColor.b, nowColor.a);
        ellipse(0, 0, nowThickness * 2, nowThickness * 2 * 0.3);


        // fill(nowColor.h, nowColor.s, nowColor.b, nowColor.a);
        // NYArc(0, 0, nowThickness, nowThickness * 0.3 * random(0.8, 1.2));

        pop();
    }
}

function NYArc(_x, _y, _width, _height) {
    let dotCount = PI * _width * dotDensity;

    for (let i = 0; i < dotCount; i++) {
        var t = i / (dotCount - 1);
        let curveT = 0;
        if (t < 0.5)
            curveT = easeOutCubic(t * 2);
        else
            curveT = easeOutCubic(1 - (t - 0.5) * 2);

        var nowThickness = lerp(-3, 3, curveT);
        if (nowThickness <= 0)
            continue;

        let angle = -90 + t * 360;

        var nowX = _x + _width * cos(radians(angle));
        var nowY = _y + _height * sin(radians(angle));

        circle(nowX, nowY, nowThickness);
    }

}

// === Tab: helper.js ===
function NYLerpHue(_hueA, _hueB, _t) {
  let hueA = _hueA;
  let hueB = _hueB;

  let hueDiff = abs(hueB - hueA);

  if (abs((hueB - 360) - hueA) < hueDiff) {
    hueB -= 360;
  }
  else if (abs((hueB + 360) - hueA) < hueDiff) {
    hueB += 360;
  }
  else {
    return lerp(_hueA, _hueB, _t);
  }

  let resultHue = lerp(hueA, hueB, _t);

  if (resultHue < 0) {
    resultHue += 360;
  }
  else if (resultHue > 360) {
    resultHue -= 360;
  }

  return resultHue;
}

function NYLerpColor(_colorA, _colorB, _t) {
  let _hue = NYLerpHue(_colorA.h, _colorB.h, _t);
  let _sat = lerp(_colorA.s, _colorB.s, _t);
  let _bri = lerp(_colorA.b, _colorB.b, _t);
  let _alpha = lerp(_colorA.a, _colorB.a, _t);

  return new NYColor(_hue, _sat, _bri, _alpha);
}

function NYLerpP5Color(_colorA, _colorB, _t) {
  var hueA = hue(_colorA);
  var hueB = hue(_colorB);

  var hueDiff = abs(hueB - hueA);

  if (abs((hueB - 360) - hueA) < hueDiff) {
    hueB -= 360;
  }
  else if (abs((hueB + 360) - hueA) < hueDiff) {
    hueB += 360;
  }
  else {
    return lerpColor(_colorA, _colorB, _t);
  }

  let satA = saturation(_colorA);
  let briA = brightness(_colorA);
  let alphaA = alpha(_colorA);

  let satB = saturation(_colorB);
  let briB = brightness(_colorB);
  let alphaB = alpha(_colorB);

  var resultHue = lerp(hueA, hueB, _t);
  let resultSat = lerp(satA, satB, _t);
  let resultBri = lerp(briA, briB, _t);
  let resultAlpha = lerp(alphaA, alphaB, _t);

  if (resultHue < 0) {
    resultHue += 360;
  }
  else if (resultHue > 360) {
    resultHue -= 360;
  }

  return color(resultHue, resultSat, resultBri, resultAlpha);
}

function processHue(_hue) {
  var result = _hue % 360;
  if (result < 0) {
    result += 360;
  }
  return result;
}

// get angle between two points and return in degrees
function getAngle(_x1, _y1, _x2, _y2) {
  let xDiff = _x2 - _x1;
  let yDiff = _y2 - _y1;
  return atan2(yDiff, xDiff) * 180 / PI + 90;
}

